// Pure data: no Three dependency. Official944814: Begin assembly excluded.
const l=s=>s.split('|'),url='https://help.prusa3d.com/guide/how-to-replace-the-chamber-fan-core-one_944814';
const officialNumbers={"964416": 2, "964450": 3, "964476": 4, "964538": 5, "964584": 6, "964730": 7, "964766": 8, "964792": 9, "964821": 10, "966028": 11, "965686": 12, "966134": 13, "969929": 14, "969955": 15, "969945": 16, "969963": 17, "969973": 18, "964847": 19, "964885": 20, "964929": 21, "979659": 22};
const step=(id,action,title,body,refs)=>({officialId:id,officialStep:officialNumbers[id],number:officialNumbers[id],action,title:l(title),body:l(body),refs,source:url+'#'+id});
export const CHAMBER_FAN_TASK={id:'chamber-fan',category:2,revision:1,title:l('チャンバーファンを交換する|Replace the chamber fans|Výměna komorových ventilátorů|Kammerlüfter austauschen'),interval:l('故障・交換が必要なとき|When replacement is needed|Při potřebě výměny|Bei erforderlichem Austausch'),source:url,steps:[
 step(964416,'cf-intro','交換する部品を確認する|Identify the replacement|Určení výměny|Austausch bestimmen','背面のチャンバーファン2個が対象です。ホットエンドファンやプリントファンとは別の部品です。必要に応じて1個または2個を交換します。取り外したネジや部品は再使用するので保管してください。ファンの向きとラベルは、この手順の写真でも確認できます。|This guide covers the two chamber fans at the rear of the printer. They are separate from the hotend fan and print fan. Replace one or both as needed. Keep the removed screws and other parts for reassembly. Use the photos in this step to check the fan orientation and labels.|Tento postup je určen pro dva zadní komorové ventilátory. Nejde o ventilátor hotendu ani tiskový ventilátor. Podle potřeby vyměňte jeden nebo oba. Šrouby a ostatní demontované díly uschovejte pro zpětnou montáž. Orientaci ventilátorů a štítky zkontrolujte podle fotografií v tomto kroku.|Diese Anleitung gilt für die beiden Kammerlüfter an der Rückseite des Druckers. Hotend- und Drucklüfter sind andere Bauteile. Ersetzen Sie je nach Bedarf einen oder beide Kammerlüfter. Bewahren Sie Schrauben und andere ausgebaute Teile für den Zusammenbau auf. Prüfen Sie Ausrichtung und Etiketten anhand der Fotos in diesem Schritt.',[70,72]),
 step(964450,'cf-tools','工具を準備する|Prepare tools|Příprava nářadí|Werkzeug vorbereiten','2.5 mm六角レンチを用意します。ナイロンリベットを持ち上げるニッパーは任意です。刃で配線を傷つけないように扱います。|Prepare a 2.5 mm Allen key. Flush cutters are optional for lifting nylon rivets; keep cutting edges clear of wiring.|Připravte imbus 2,5 mm. Štípací kleště pro nadzvednutí nylonových nýtů jsou volitelné; ostří držte mimo kabely.|2,5-mm-Innensechskantschlüssel bereitlegen. Seitenschneider zum Anheben der Nylonnieten sind optional; Schneiden von Kabeln fernhalten.',[70,72]),
 step(964476,'cf-safe','ホーム・ベッド下降後に冷却・電源切断する|Home, lower the bed, cool and disconnect|Zaparkování, spuštění podložky a odpojení|Homen, Bett absenken, abkühlen und trennen','印刷を停止します。動作できる状態でControl → Auto Homeを実行し、完了を待ちます。Control → Move Axis → Move Zでベッドを100 mm以上下降させ、停止を待ちます。熱い部分が室温まで冷えてから背面スイッチをOFFにし、電源コードを抜きます。以降、再組立てが終わるまで通電しません。|Stop printing. While the printer is operational, use Control → Auto Home and wait. Use Control → Move Axis → Move Z to lower the bed by at least 100 mm; wait for it to stop. Let hot parts cool to room temperature, switch the rear power OFF and unplug. Keep power disconnected until reassembly is complete.|Zastavte tisk. U provozuschopné tiskárny proveďte Control → Auto Home a vyčkejte. Přes Control → Move Axis → Move Z spusťte podložku alespoň o 100 mm a počkejte na zastavení. Nechte horké díly vychladnout na pokojovou teplotu, vypněte zadní vypínač a odpojte kabel. Do dokončení montáže nezapínejte.|Druck stoppen. Bei betriebsbereitem Drucker Control → Auto Home ausführen und warten. Über Control → Move Axis → Move Z das Bett mindestens 100 mm absenken und Stillstand abwarten. Heiße Teile auf Raumtemperatur abkühlen lassen, hinten ausschalten und Netzstecker ziehen. Bis zum Zusammenbau stromlos lassen.',['heatbed','sheet','bedSupport']),
 step(964538,'cf-top-out','トップカバーを外す|Remove top cover|Sejmutí horního krytu|Obere Abdeckung abnehmen','内側の右前からナイロンリベットのピンを押し出してロックを外し、外側から抜きます。残りも同様に外して保管し、トップカバーを持ち上げます。各ピンの解除方向と実機の留め具の位置を公式写真でも照合します。|From inside the front-right corner, push the nylon-rivet pin out to unlock, then remove it from outside. Repeat for the others, retain them and lift the top cover. Check the pin-release direction and actual fastener locations against the official photos.|Zevnitř pravého předního rohu vytlačte kolík nylonového nýtu, odjistěte jej a zvenku vyjměte. Opakujte u ostatních, uschovejte je a zvedněte kryt. Směr odjištění kolíků a polohu skutečných nýtů porovnejte s oficiální fotografií.|Innen vorn rechts den Stift der Nylonniete herausdrücken, entriegeln und außen herausnehmen. Bei den übrigen wiederholen, aufbewahren und Deckel anheben. Entriegelungsrichtung der Stifte und tatsächliche Positionen mit dem offiziellen Foto vergleichen.',[87]),
 step(964584,'cf-protect','ベッドを保護する|Protect the heatbed|Ochrana podložky|Heizbett schützen','これ以降の作業前に、布・段ボール・緩衝材など柔らかい保護材をベッドへ敷き、ヒートベッドとシートを落下部品から守ります。|Before continuing, cover the bed with cloth, cardboard, bubble wrap or another soft mat to protect the heatbed and sheet from dropped parts.|Před pokračováním zakryjte podložku látkou, kartonem, bublinkovou fólií nebo měkkou podložkou proti padajícím dílům.|Vor weiteren Arbeiten das Bett mit Stoff, Karton, Luftpolsterfolie oder einer weichen Matte vor herabfallenden Teilen schützen.',['heatbed','sheet']),
 step(964730,'cf-side-top-out','上側のサイドカバーを外す|Remove upper side cover|Sejmutí horního bočního krytu|Obere Seitenabdeckung abnehmen','公式写真のナイロンリベット5本を外します。必要ならニッパーで上側のピンを持ち上げてロックを外し、下側を抜きます。カバーとリベットを保管します。|Remove the five nylon rivets shown. If needed lift each upper pin with flush cutters to unlock, then withdraw the lower body. Retain cover and rivets.|Vyjměte pět označených nylonových nýtů. Případně kleštěmi nadzvedněte horní kolík a odjistěte, pak vytáhněte spodní tělo. Kryt i nýty uschovejte.|Die fünf gezeigten Nylonnieten entfernen. Bei Bedarf oberen Stift mit dem Seitenschneider anheben und entriegeln, dann Unterteil herausziehen. Abdeckung und Nieten aufbewahren.',[83]),
 step(964766,'cf-side-out','サイドの板金パネルを外す|Remove side sheet panel|Sejmutí bočního plechu|Seitliches Blech abnehmen','写真で指定されたナイロンリベット11本を1本ずつ抜いて保管し、パネルを支えながら取り外します。反対側のパネルや無関係なネジは外しません。|Remove and retain the eleven marked nylon rivets individually, then support and remove the side panel. Leave the opposite panel and unrelated screws fitted.|Jednotlivě vyjměte a uschovejte jedenáct označených nýtů, podepřete a sejměte boční plech. Protější panel a nesouvisející šrouby ponechte.|Die elf markierten Nylonnieten einzeln entfernen und aufbewahren, dann das Seitenblech gestützt abnehmen. Gegenüberliegendes Blech und andere Schrauben bleiben montiert.',[48]),
 step(964792,'cf-rear-out','配線用のバックカバーを外す|Remove rear wiring cover|Sejmutí zadního krytu kabeláže|Hintere Kabelabdeckung abnehmen','内側のM3×4rTを2本外します。カバーを中央で下へ押し、上端4か所の爪が全て外れたことを確認して少し後方へ動かします。下側を手前へ、上側を本体へ傾け、配線束に引っ掛けず外します。|Remove the two inner M3×4rT screws. Push the cover down at its centre, check all four upper tabs are free, then move it slightly rearward. Tilt the bottom outward and top toward the printer to unhook it without catching the cable bundle.|Vyjměte dva vnitřní šrouby M3×4rT. Uprostřed stlačte kryt dolů, ověřte uvolnění všech čtyř horních jazýčků a posuňte mírně dozadu. Spodek vyklopte ven a vršek k tiskárně, aniž zachytíte svazek.|Die beiden inneren M3×4rT entfernen. Abdeckung mittig nach unten drücken, alle vier oberen Laschen lösen und etwas nach hinten bewegen. Unten nach außen, oben zum Drucker kippen, ohne den Kabelbaum einzuhaken.',[78,146,148]),
 step(964821,'cf-box-out','xBuddyカバーを外す|Remove xBuddy cover|Sejmutí krytu xBuddy|xBuddy-Abdeckung abnehmen','M3×4rTを6本、1本ずつ外して保管し、カバーをスライドさせて取り外します。基板や他のコネクターは外しません。|Remove and retain the six M3×4rT screws individually, then slide off the cover. Leave boards and other connectors fitted.|Jednotlivě vyjměte a uschovejte šest M3×4rT a vysuňte kryt. Desky a ostatní konektory ponechte.|Sechs M3×4rT einzeln entfernen und aufbewahren, dann die Abdeckung herausschieben. Platinen und andere Stecker bleiben montiert.',[206,193,195,197,199,201,203]),
 step(966028,'cf-unplug','ファン2本とTEMPを1個ずつ外す|Disconnect both fans and TEMP individually|Jednotlivé odpojení ventilátorů a TEMP|Beide Lüfter und TEMP einzeln abstecken','配線を切らないよう結束バンドだけを切ります。各コネクターの安全ラッチを先に押して解除し、本体をつかんでまっすぐ抜きます。チャンバーサーミスターTEMP、チャンバーファン2本を外してボックスから配線を引き出します。ボックス上部のグロメットは残します。|Cut only the cable tie, protecting the wires. Press each connector safety latch first, grip its housing and withdraw straight. Disconnect chamber-thermistor TEMP and both chamber fans, then withdraw their leads from the box. Leave the upper box grommets fitted.|Přestřihněte jen pásku, ne vodiče. Nejprve stiskněte pojistku každého konektoru, uchopte tělo a vytáhněte přímo. Odpojte TEMP komorového termistoru a oba ventilátory, kabely vytáhněte z boxu. Horní průchodky ponechte.|Nur den Kabelbinder durchtrennen und Leitungen schützen. Jede Verriegelung zuerst drücken, am Gehäuse greifen und gerade abziehen. Kammerthermistor TEMP und beide Lüfter abstecken, Kabel aus dem Gehäuse führen. Obere Tüllen montiert lassen.',['xBuddyExtension','cfTemp','cfFan1','cfFan2']),
 step(965686,'cf-fans-out','グリッドと両ファンを取り外す|Remove grid and both fans|Demontáž mřížky a obou ventilátorů|Gitter und beide Lüfter ausbauen','本体を回して内側から作業します。ファンを支え、M3×30を4本外します。サーミスター付きグリッドを外し、その配線を背板とCoreXYの穴から抜きます。続いて両ファンの配線を同じ穴から抜き、本体も取り外します。背板のグロメットは残し、旧ファンは新品と混ざらない場所へ置きます。|Turn the printer to work from inside. Support the fans and remove four M3×30 screws. Remove the grid with its thermistor, feeding its lead through the rear-panel and CoreXY openings. Feed both fan leads through the same openings and remove both fans. Keep the rear grommet fitted; park old fans apart from replacements.|Otočte tiskárnu pro práci zevnitř. Ventilátory podepřete a vyjměte čtyři M3×30. Sejměte mřížku s termistorem a protáhněte jeho kabel otvory zadního plechu a CoreXY. Stejnými otvory vytáhněte oba kabely a vyjměte ventilátory. Průchodku ponechte; staré ventilátory odložte odděleně od nových.|Drucker drehen und von innen arbeiten. Lüfter stützen und vier M3×30 entfernen. Gitter samt Thermistor abnehmen und dessen Kabel durch Rückwand- und CoreXY-Öffnung ziehen. Beide Lüfterkabel durch dieselben Öffnungen herausführen und Lüfter entnehmen. Tülle bleibt; alte Lüfter getrennt von neuen ablegen.',[138,140,142,144,71,70,72]),
 step(966134,'cf-parts','交換品と新しい結束バンドを用意する|Prepare replacements and a new tie|Příprava náhrad a nové pásky|Ersatz und neuen Kabelbinder vorbereiten','交換するファンを1個または2個と、新しい結束バンド1本を用意します。1個だけ交換する場合、もう片方は元の正常なファンを再使用できます。外したグリッド・サーミスター・ネジは再使用します。|Prepare one or two replacement fans and one new cable tie. When replacing one fan, reuse the other serviceable original. Reuse the removed grid, thermistor and screws.|Připravte jeden nebo dva nové ventilátory a jednu novou pásku. Při výměně jednoho lze druhý funkční původní použít znovu. Mřížku, termistor a šrouby znovu použijte.|Einen oder zwei Ersatzlüfter und einen neuen Kabelbinder bereitlegen. Beim Austausch eines Lüfters den anderen intakten weiterverwenden. Gitter, Thermistor und Schrauben wiederverwenden.',[70,72,71]),
 step(969929,'cf-fans-in','向きを合わせ、両ファンと配線を置く|Orient and place both fans and leads|Orientace a vložení obou ventilátorů|Beide Lüfter samt Kabeln ausrichten','両ファンをCoreXYの上へ置きます。ステッカーのない面を前方へ、ケーブルを中央側の角へ向けます。背板のグロメットを残し、両ケーブルをCoreXYの楕円穴へ通します。まだネジで固定しません。|Place both fans on top of CoreXY with the non-sticker face forward and cable exits at the central corners. Leave the rear grommet in place and pass both leads through the CoreXY oval opening. Do not fasten yet.|Oba ventilátory položte na CoreXY stranou bez štítku dopředu a kabely ze středových rohů. Zadní průchodku ponechte a oba kabely protáhněte oválným otvorem CoreXY. Zatím nešroubujte.|Beide Lüfter auf CoreXY legen: Seite ohne Aufkleber nach vorn, Kabel an den mittleren Ecken. Hintere Tülle belassen und beide Kabel durch die ovale CoreXY-Öffnung führen. Noch nicht verschrauben.',[70,72]),
 step(969955,'cf-grid-in','サーミスター付きグリッドを置く|Place grid with thermistor|Vložení mřížky s termistorem|Gitter mit Thermistor einsetzen','グロメットを残し、サーミスターのケーブルもCoreXYの穴へ通します。グリッドをファンの前へ置き、センサーを前向きにします。金属センサーをグリッドへ接触させません。背面から全ケーブルの穴通過とグロメットの正しい装着を確認します。|Keep the grommet fitted and pass the thermistor lead through the CoreXY opening. Place the grid in front of the fans, sensor facing forward. Its metal sensor must not touch the grid. From the rear check all leads pass through the openings and the grommet is seated.|Ponechte průchodku a protáhněte kabel termistoru otvorem CoreXY. Mřížku položte před ventilátory se senzorem dopředu. Kovový senzor se nesmí dotýkat mřížky. Zezadu ověřte vedení všech kabelů a usazení průchodky.|Tülle belassen und Thermistorkabel durch die CoreXY-Öffnung führen. Gitter vor die Lüfter setzen, Sensor nach vorn. Metallsensor darf das Gitter nicht berühren. Hinten alle Kabeldurchführungen und Tüllensitz prüfen.',[71,'cfTemp']),
 step(969945,'cf-fasten','支えながら4本を軽く締める|Support and gently fasten four screws|Podepření a mírné dotažení čtyř šroubů|Vier Schrauben gestützt leicht festziehen','M3×30を1本グリッドとファンへ通し、背板へ仮止めします。片手で両ファンを支え、残り3本も緩く入れます。全4本を入れてから少しずつ慎重に締め、反対側から位置を確認します。締め過ぎると印刷製グリッドが割れるため、軽く固定するだけにします。|Pass one M3×30 through grid and fan and loosely start it in the rear panel. Support both fans with the other hand and loosely fit the other three. Only after all four are started, tighten gradually and carefully, checking alignment from the opposite side. Tighten only lightly: overtightening can crack the printed grid.|Jeden M3×30 prostrčte mřížkou a ventilátorem a lehce zachyťte do zadního plechu. Druhou rukou podepřete oba ventilátory a volně vložte další tři. Až jsou všechny čtyři zachycené, opatrně postupně dotáhněte a z protější strany zkontrolujte polohu. Jen lehce; přetažení může rozlomit tištěnou mřížku.|Einen M3×30 durch Gitter und Lüfter stecken und hinten lose ansetzen. Beide Lüfter mit der anderen Hand stützen, die übrigen drei lose einsetzen. Erst dann alle vier schrittweise vorsichtig anziehen und gegenüber die Ausrichtung prüfen. Nur leicht festziehen; Überdrehen kann das gedruckte Gitter brechen.',[138,140,142,144,70,72,71]),
 step(969963,'cf-connect','FAN1・FAN2・TEMPへ接続する|Connect FAN1, FAN2 and TEMP|Zapojení FAN1, FAN2 a TEMP|FAN1, FAN2 und TEMP anschließen','背面へ回ります。ボックスのグロメットを残し、ファン2本を上部右側の穴から入れ、FAN1とFAN2へ1本ずつまっすぐ接続します（ファンの左右とFAN1/2の組み合わせは任意）。サーミスターは左側の穴からTEMPへ接続します。最後に新しい結束バンド1本で配線をまとめ、締め過ぎ・引張り・挟み込みを避けます。|Work from the rear. Keep the box grommets fitted. Feed both fan leads through the upper right opening and connect FAN1 and FAN2 individually, straight in; either fan may use either port. Feed the thermistor through the left opening to TEMP. Finally secure the leads with one new tie without overtightening, strain or trapping.|Pracujte zezadu. Průchodky ponechte. Oba kabely ventilátorů veďte horním pravým otvorem a jednotlivě přímo zapojte do FAN1 a FAN2; přiřazení ventilátorů je libovolné. Termistor veďte levým otvorem do TEMP. Nakonec zajistěte jednou novou páskou bez přetažení, tahu a skřípnutí.|Von hinten arbeiten, Tüllen belassen. Beide Lüfterkabel durch die obere rechte Öffnung führen und einzeln gerade in FAN1/FAN2 einstecken; Zuordnung der Lüfter ist beliebig. Thermistor links durchführen und an TEMP anschließen. Zuletzt mit einem neuen Kabelbinder ohne Überziehen, Zug oder Quetschung sichern.',['xBuddyExtension','cfFan1','cfFan2','cfTemp']),
 step(969973,'cf-box-in','xBuddyカバーを戻す|Refit xBuddy cover|Vrácení krytu xBuddy|xBuddy-Abdeckung montieren','配線を挟まないよう、曲がった縁を先に差し込んでカバーをスライドさせます。保管したM3×4rTを6本戻します。|Slide the cover in bent-edge first without trapping cables. Refit the six retained M3×4rT screws.|Kryt zasuňte nejprve zahnutou hranou, neskřípněte kabely. Vraťte šest uschovaných M3×4rT.|Abdeckung mit gebogener Kante zuerst einschieben, ohne Kabel einzuklemmen. Sechs aufbewahrte M3×4rT montieren.',[206,193,195,197,199,201,203]),
 step(964847,'cf-rear-in','ケーブルをトレーの上にしてバックカバーを戻す|Refit rear cover with cables above tray|Vrácení zadního krytu s kabely nad vaničkou|Rückabdeckung mit Kabeln über der Ablage montieren','ケーブルはカバーのトレーより上へ逃がします。カバーを凹みに合わせて内側へ押し、次に上へ動かして上端4か所の爪を全て掛けます。内側のM3×4rTを2本戻します。|Keep cables above the cover tray. Align the cover in its recess, push inward and then upward until all four upper tabs engage. Refit the two inner M3×4rT screws.|Kabely ponechte nad vaničkou krytu. Kryt vložte do vybrání, zatlačte dovnitř a pak vzhůru, aby zapadly všechny čtyři jazýčky. Vraťte dva vnitřní M3×4rT.|Kabel oberhalb der Ablage halten. Abdeckung in die Aussparung setzen, nach innen und dann nach oben drücken, bis alle vier Laschen greifen. Beide inneren M3×4rT montieren.',[78,146,148]),
 step(964885,'cf-side-in','サイドの板金とカバーを戻す|Refit side sheet and cover|Vrácení bočního plechu a krytu|Seitenblech und Abdeckung montieren','板金パネルの穴をフレームへ合わせ、ナイロンリベット11本を戻します。続いて上側のプラスチックカバーを合わせ、5本を戻します。ピンを押して各リベットをロックします。|Align the sheet-panel holes with the frame and refit eleven nylon rivets. Align the upper plastic cover and refit its five rivets. Press the pins to lock each rivet.|Vyrovnejte otvory plechu s rámem a vraťte jedenáct nýtů. Pak nasaďte horní plastový kryt a jeho pět nýtů. Stisknutím kolíků každý nýt zajistěte.|Blechlöcher am Rahmen ausrichten und elf Nylonnieten einsetzen. Obere Kunststoffabdeckung ausrichten und fünf Nieten einsetzen. Stifte zum Verriegeln eindrücken.',[48,83]),
 step(964538,'cf-restore','保護材を取り出し、トップカバーを戻す|Remove the bed protection and refit the top cover|Vyjmutí ochrany podložky a nasazení horního krytu|Bettschutz entfernen und obere Abdeckung montieren','追加の復旧確認です。ベッドの保護材と置き忘れた部品・工具を全て取り出します。外したトップカバーを戻し、保管した留め具を元の穴でロックします。配線が羽根・カバー・可動部に触れないことを確認してから電源へ進みます。|Additional restoration check: remove the bed protection and all loose parts and tools. Refit the removed top cover and lock the retained fasteners in their original holes. Check leads are clear of blades, covers and moving parts before reconnecting power.|Doplňková kontrola: odstraňte ochranu podložky, volné díly i nářadí. Vraťte horní kryt a zajistěte původní spojovací díly v původních otvorech. Před připojením ověřte odstup kabelů od lopatek, krytů a pohyblivých částí.|Zusätzliche Wiederherstellung: Bettschutz, lose Teile und Werkzeuge entfernen. Oberen Deckel aufsetzen und aufbewahrte Befestigungen in ursprünglichen Löchern verriegeln. Vor Netzanschluss Leitungen auf Abstand zu Flügeln, Abdeckungen und beweglichen Teilen prüfen.',[87,'heatbed']),
 step(964929,'cf-power','電源を接続してONにする|Reconnect power and switch ON|Připojení a zapnutí|Netz anschließen und einschalten','全カバーと固定を確認した後、電源コードを接続し、背面スイッチをONにします。|After checking all covers and fasteners, plug in the power cord and switch the rear power ON.|Po kontrole krytů a upevnění připojte napájecí kabel a zapněte zadní vypínač.|Nach Kontrolle aller Abdeckungen und Befestigungen Netzkabel anschließen und hinten einschalten.',[70,72]),
 step(979659,'cf-test','実機のFan Testで確認する|Run the actual Fan Test|Skutečný test ventilátorů|Lüftertest am Drucker ausführen','写真と組み立てた状態を見比べてから、実機でControl → Calibrations & Tests → Fan Testを実行します。2つのチャンバーファンが回り、エラーが出ないことを確認してください。異音がする、または回らない場合は使用を止め、電源を切って電源コードを抜いてから、接続や配線、ファンへの接触を確認します。|Compare the assembled parts with the photos, then run Control → Calibrations & Tests → Fan Test on the printer. Check that both chamber fans turn and the test reports no error. If a fan does not turn or makes an unusual noise, stop using the printer. Switch it off and unplug the power cable before checking the connections, wiring and anything touching the fan.|Porovnejte sestavu s fotografiemi a na tiskárně spusťte Control → Calibrations & Tests → Fan Test. Ověřte, že se oba komorové ventilátory otáčejí a test nehlásí chybu. Pokud se ventilátor netočí nebo vydává neobvyklý zvuk, tiskárnu přestaňte používat. Před kontrolou konektorů, kabeláže a případných překážek ji vypněte a odpojte napájecí kabel.|Vergleichen Sie den Zusammenbau mit den Fotos und starten Sie am Drucker Control → Calibrations & Tests → Fan Test. Prüfen Sie, ob beide Kammerlüfter laufen und der Test keinen Fehler meldet. Wenn ein Lüfter stillsteht oder ungewöhnliche Geräusche macht, verwenden Sie den Drucker nicht weiter. Schalten Sie ihn aus und ziehen Sie den Netzstecker, bevor Sie Anschlüsse, Kabel und mögliche Berührungen am Lüfter prüfen.',[70,72])
]};

CHAMBER_FAN_TASK.steps.forEach((s,i)=>s.localNumber=i+1);
CHAMBER_FAN_TASK.steps[19].derivedRestoration=true;
CHAMBER_FAN_TASK.steps.find(s=>s.action==='cf-safe').firmwareActions=['home','moveZ','cooldown'];
CHAMBER_FAN_TASK.steps.find(s=>s.action==='cf-test').firmwareActions=['fans'];
